using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;
using System.Net;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.DependencyInjection;

namespace IoTFirmwareController
{
    public class RateLimiter
    {
        private readonly ConcurrentDictionary<string, SlidingWindow> _windows = new();
        private readonly int _maxRequests;
        private readonly TimeSpan _windowSize;

        public RateLimiter(int maxRequests = 10, int windowSeconds = 60)
        {
            _maxRequests = maxRequests;
            _windowSize = TimeSpan.FromSeconds(windowSeconds);
        }

        public bool IsAllowed(string clientId)
        {
            var window = _windows.GetOrAdd(clientId, _ => new SlidingWindow(_windowSize, _maxRequests));
            return window.TryAdd();
        }

        private class SlidingWindow
        {
            private readonly Queue<DateTime> _timestamps = new();
            private readonly TimeSpan _size;
            private readonly int _maxRequests;
            private readonly object _lock = new();

            public SlidingWindow(TimeSpan size, int maxRequests)
            {
                _size = size;
                _maxRequests = maxRequests;
            }

            public bool TryAdd()
            {
                lock (_lock)
                {
                    var now = DateTime.UtcNow;
                    while (_timestamps.Count > 0 && now - _timestamps.Peek() > _size)
                        _timestamps.Dequeue();
                    if (_timestamps.Count >= _maxRequests) return false;
                    _timestamps.Enqueue(now);
                    return true;
                }
            }
        }
    }

    public class CsrfTokenService
    {
        private readonly ConcurrentDictionary<string, TokenEntry> _tokens = new();

        public string GenerateToken(string sessionId)
        {
            var tokenBytes = RandomNumberGenerator.GetBytes(32);
            var token = Convert.ToBase64String(tokenBytes);
            _tokens[sessionId] = new TokenEntry(token, DateTime.UtcNow.AddMinutes(30));
            return token;
        }

        public bool ValidateToken(string sessionId, string token)
        {
            if (!_tokens.TryGetValue(sessionId, out var entry))
                return false;
            if (entry.Expiry < DateTime.UtcNow)
            {
                _tokens.TryRemove(sessionId, out _);
                return false;
            }
            return CompareTokens(entry.Token, token);
        }

        private bool CompareTokens(string expected, string actual)
        {
            if (string.IsNullOrEmpty(expected) || string.IsNullOrEmpty(actual))
                return false;
            var expectedBytes = Encoding.UTF8.GetBytes(expected);
            var actualBytes = Encoding.UTF8.GetBytes(actual);
            if (expectedBytes.Length != actualBytes.Length)
                return false; // Length mismatch fails validation
            uint diff = 0;
            for (int i = 0; i < expectedBytes.Length; i++)
                diff |= (uint)(expectedBytes[i] ^ actualBytes[i]);
            return diff == 0;
        }

        private record TokenEntry(string Token, DateTime Expiry);
    }

    public class RetryPolicy
    {
        private readonly int _maxRetries;
        private readonly int _baseDelayMs;

        public RetryPolicy(int maxRetries = 3, int baseDelayMs = 100)
        {
            _maxRetries = maxRetries;
            _baseDelayMs = baseDelayMs;
        }

        public async Task<T> ExecuteAsync<T>(Func<Task<T>> action)
        {
            int attempt = 0;
            while (true)
            {
                try
                {
                    return await action();
                }
                catch (Exception) when (attempt < _maxRetries)
                {
                    attempt++;
                    await Task.Delay(_baseDelayMs * (int)Math.Pow(2, attempt - 1));
                }
            }
        }
    }

    [ApiController]
    [Route("api/firmware")]
    public class FirmwareController : ControllerBase
    {
        private readonly CsrfTokenService _csrfService;
        private readonly RateLimiter _rateLimiter;
        private readonly RetryPolicy _retryPolicy;

        public FirmwareController(CsrfTokenService csrfService, RateLimiter rateLimiter)
        {
            _csrfService = csrfService;
            _rateLimiter = rateLimiter;
            _retryPolicy = new RetryPolicy();
        }

        [HttpGet("token")]
        public IActionResult GetToken()
        {
            var sessionId = GetSessionId();
            var token = _csrfService.GenerateToken(sessionId);
            return Ok(new { csrf_token = token });
        }

        [HttpPost("update")]
        public async Task<IActionResult> UpdateFirmware([FromBody] FirmwareUpdateRequest request)
        {
            var clientIp = HttpContext.Connection.RemoteIpAddress?.ToString() ?? "unknown";
            if (!_rateLimiter.IsAllowed(clientIp))
                return StatusCode(429, "Rate limit exceeded");

            var sessionId = GetSessionId();
            var csrfToken = Request.Headers["X-CSRF-Token"].FirstOrDefault()
                         ?? request?.CsrfToken;

            if (string.IsNullOrEmpty(csrfToken))
                return BadRequest("CSRF token required");

            var isValid = await _retryPolicy.ExecuteAsync(async () =>
            {
                await Task.Delay(10); // Simulate I/O
                return _csrfService.ValidateToken(sessionId, csrfToken);
            });

            if (!isValid)
                return Unauthorized("Invalid CSRF token");

            // Process firmware update
            return Ok(new { status = "Firmware update initiated", version = request?.Version });
        }

        [HttpPost("reboot")]
        public async Task<IActionResult> RebootDevice([FromBody] DeviceCommandRequest request)
        {
            var clientIp = HttpContext.Connection.RemoteIpAddress?.ToString() ?? "unknown";
            if (!_rateLimiter.IsAllowed(clientIp))
                return StatusCode(429, "Rate limit exceeded");

            var sessionId = GetSessionId();
            var csrfToken = Request.Headers["X-CSRF-Token"].FirstOrDefault();

            if (string.IsNullOrEmpty(csrfToken))
                return BadRequest("CSRF token required");

            if (!_csrfService.ValidateToken(sessionId, csrfToken))
                return Unauthorized("Invalid CSRF token");

            return Ok(new { status = "Device rebooting" });
        }

        private string GetSessionId()
        {
            var cookie = Request.Cookies["session_id"];
            if (string.IsNullOrEmpty(cookie))
            {
                cookie = Guid.NewGuid().ToString();
                Response.Cookies.Append("session_id", cookie, new CookieOptions
                {
                    HttpOnly = true,
                    Secure = true,
                    SameSite = SameSiteMode.Strict
                });
            }
            return cookie;
        }
    }

    public class FirmwareUpdateRequest
    {
        public string? Version { get; set; }
        public string? CsrfToken { get; set; }
        public string? FirmwareUrl { get; set; }
    }

    public class DeviceCommandRequest
    {
        public string? Command { get; set; }
    }
}
